def read1(self, size: int) -> bytes:
    f = getattr(self._stream, "read1", None)

    if f is not None:
        return t.cast(bytes, f(size))

    return self._stream.read(size)

def _wrap_io_open(
    file: str | os.PathLike[str] | int,
    mode: str,
    encoding: str | None,
    errors: str | None,
) -> t.IO[t.Any]:
    """Handles not passing ``encoding`` and ``errors`` in binary mode."""
    if "b" in mode:
        return open(file, mode)

    return open(file, mode, encoding=encoding, errors=errors)

def readinto(self, b: Buffer) -> int:
    bytes_to_be_read = len(b)
    if not bytes_to_be_read:
        return 0
    elif bytes_to_be_read % 2:
        raise ValueError(
            "cannot read odd number of bytes from UTF-16-LE encoded console"
        )

    buffer = get_buffer(b, writable=True)
    code_units_to_be_read = bytes_to_be_read // 2
    code_units_read = c_ulong()

    rv = ReadConsoleW(
        HANDLE(self.handle),
        buffer,
        code_units_to_be_read,
        byref(code_units_read),
        None,
    )
    if GetLastError() == ERROR_OPERATION_ABORTED:
        # wait for KeyboardInterrupt
        time.sleep(0.1)
    if not rv:
        raise OSError(_("Windows error: {error}").format(error=GetLastError()))

    if buffer[0] == EOF:
        return 0
    return 2 * code_units_read.value

@property
def protected_args(self) -> list[str]:
    import warnings

    warnings.warn(
        "'protected_args' is deprecated and will be removed in Click 9.0."
        " 'args' will contain remaining unparsed tokens.",
        DeprecationWarning,
        stacklevel=2,
    )
    return self._protected_args

def get_help_option_names(self, ctx: Context) -> list[str]:
    """Returns the names for the help option.

    Drops duplicates and names already reserved by another parameter. Order of
    :attr:`Context.help_option_names` is preserved, so the result is stable.

    .. versionchanged:: 8.5.0
        Names keep their declaration order.
    """
    all_names = dict.fromkeys(ctx.help_option_names)
    for param in self.params:
        for name in (*param.opts, *param.secondary_opts):
            all_names.pop(name, None)
    return list(all_names)

def invoke(self, ctx: Context) -> t.Any:
    """Given a context, this invokes the attached callback (if it exists)
    in the right way.
    """
    if self.deprecated:
        message = _(
            "DeprecationWarning: The command {name!r} is deprecated.{extra_message}"
        ).format(
            name=self.name,
            extra_message=_format_deprecated_suffix(self.deprecated),
        )
        echo(style(message, fg="red"), err=True)

    if self.callback is not None:
        return ctx.invoke(self.callback, **ctx.params)

def _param_memo(f: t.Callable[..., t.Any], param: Parameter) -> None:
    if isinstance(f, Command):
        f.params.append(param)
    else:
        if not hasattr(f, "__click_params__"):
            f.__click_params__ = []  # type: ignore

        f.__click_params__.append(param)  # type: ignore

def show(self, file: t.IO[t.Any] | None = None) -> None:
    if file is None:
        file = get_text_stderr()

    echo(
        _("Error: {message}").format(message=self.format_message()),
        file=file,
        color=self.show_color,
    )

def _interpret_color(color: int | tuple[int, int, int] | str, offset: int = 0) -> str:
    """Interprets a color value and returns the corresponding ANSI code."""
    if isinstance(color, str) and color in _ansi_colors:
        return str(_ansi_colors[color] + offset)

    # bool is an int subclass: without the exclusion, True and False would
    # silently render as the palette indices 1 and 0.
    elif isinstance(color, int) and not isinstance(color, bool):
        if 0 <= color <= 255:
            return f"{38 + offset};5;{color:d}"

    elif (
        isinstance(color, (tuple, list))
        and len(color) == 3
        and all(
            isinstance(c, int) and not isinstance(c, bool) and 0 <= c <= 255
            for c in color
        )
    ):
        r, g, b = color
        return f"{38 + offset};2;{r:d};{g:d};{b:d}"

    raise ValueError(_("Unknown color {colour!r}").format(colour=color))

def _normalized_mapping(
    self, ctx: Context | None = None
) -> cabc.Mapping[_ValueT_co, str]:
    """
    Returns mapping where keys are the original choices and the values are
    the normalized values that are accepted via the command line.

    This is a simple wrapper around :meth:`normalize_choice`, use that
    instead which is supported.
    """
    return {
        choice: self.normalize_choice(
            choice=choice,
            ctx=ctx,
        )
        for choice in self.choices
    }

def convert(
    self, value: t.Any, param: Parameter | None, ctx: Context | None
) -> bool:
    normalized = self.str_to_bool(value)
    if normalized is None:
        self.fail(
            _(
                "{value!r} is not a valid boolean. Recognized values: {states}"
            ).format(value=value, states=", ".join(sorted(self.bool_states))),
            param,
            ctx,
        )
    return normalized

def close_intelligently(self) -> None:
    """This function only closes the file if it was opened by the lazy
    file wrapper.  For instance this will never close stdin.
    """
    if self.should_close:
        self.close()

def get_dict(
    self, domain: str | None = None, path: str | None = None
) -> dict[str, str | None]:
    """Takes as an argument an optional domain and path and returns a plain
    old Python dict of name-value pairs of cookies that meet the
    requirements.

    :rtype: dict
    """
    dictionary: dict[str, str | None] = {}
    for cookie in iter(self):
        if (domain is None or cookie.domain == domain) and (
            path is None or cookie.path == path
        ):
            dictionary[cookie.name] = cookie.value
    return dictionary

def set_cookie(self, cookie: Cookie, *args: Any, **kwargs: Any) -> None:
    if (
        (value := cookie.value) is not None
        and value.startswith('"')
        and value.endswith('"')
    ):
        cookie.value = value.replace('\\"', "")
    return super().set_cookie(cookie, *args, **kwargs)

def _find(
    self, name: str, domain: str | None = None, path: str | None = None
) -> str | None:
    """Requests uses this method internally to get cookie values.

    If there are conflicting cookies, _find arbitrarily chooses one.
    See _find_no_duplicates if you want an exception thrown if there are
    conflicting cookies.

    :param name: a string containing name of cookie
    :param domain: (optional) string containing domain of cookie
    :param path: (optional) string containing path of cookie
    :return: cookie.value
    """
    for cookie in iter(self):
        if cookie.name == name:
            if domain is None or cookie.domain == domain:
                if path is None or cookie.path == path:
                    return cookie.value

    raise KeyError(f"name={name!r}, domain={domain!r}, path={path!r}")

def _find_no_duplicates(
    self, name: str, domain: str | None = None, path: str | None = None
) -> str:
    """Both ``__get_item__`` and ``get`` call this function: it's never
    used elsewhere in Requests.

    :param name: a string containing name of cookie
    :param domain: (optional) string containing domain of cookie
    :param path: (optional) string containing path of cookie
    :raises KeyError: if cookie is not found
    :raises CookieConflictError: if there are multiple cookies
        that match name and optionally domain and path
    :return: cookie.value
    """
    toReturn = None
    for cookie in iter(self):
        if cookie.name == name:
            if domain is None or cookie.domain == domain:
                if path is None or cookie.path == path:
                    if toReturn is not None:
                        # if there are multiple cookies that meet passed in criteria
                        raise CookieConflictError(
                            f"There are multiple cookies with name, {name!r}"
                        )
                    # we will eventually return this as long as no cookie conflict
                    toReturn = cookie.value

    if toReturn is not None:
        return toReturn
    raise KeyError(f"name={name!r}, domain={domain!r}, path={path!r}")

def dispatch_hook(
    key: str,
    hooks: _t.HooksInputType | None,
    hook_data: Response,
    **kwargs: Any,
) -> Response:
    """Dispatches a hook dictionary on a given piece of data."""
    hooks_dict = hooks or {}
    hook_list: Iterable[_t.HookType] | _t.HookType | None = hooks_dict.get(key)
    if hook_list:
        if isinstance(hook_list, Callable):
            hook_list = [hook_list]
        for hook in hook_list:
            _hook_data = hook(hook_data, **kwargs)
            if _hook_data is not None:
                hook_data = _hook_data
    return hook_data

def prepare_content_length(self, body: _t.BodyType) -> None:
    """Prepare Content-Length header based on request method and body"""
    if body is not None:
        length = super_len(body)
        if length:
            # If length exists, set it. Otherwise, we fallback
            # to Transfer-Encoding: chunked.
            self.headers["Content-Length"] = builtin_str(length)
    elif (
        self.method not in ("GET", "HEAD")
        and self.headers.get("Content-Length") is None
    ):
        # Set Content-Length to 0 for methods that can have a body
        # but don't provide one. (i.e. not GET or HEAD)
        self.headers["Content-Length"] = "0"

@property
def ok(self) -> bool:
    """Returns True if :attr:`status_code` is less than 400, False if not.

    This attribute checks if the status code of the response is between
    400 and 600 to see if there was a client error or a server error. If
    the status code is between 200 and 400, this will return True. This
    is **not** a check to see if the response code is ``200 OK``.
    """
    try:
        self.raise_for_status()
    except HTTPError:
        return False
    return True

def iter_lines(
    self,
    chunk_size: int = ITER_CHUNK_SIZE,
    decode_unicode: bool = False,
    delimiter: str | bytes | None = None,
) -> Iterator[str | bytes]:
    """Iterates over the response data, one line at a time.  When
    stream=True is set on the request, this avoids reading the
    content at once into memory for large responses.

    The decode_unicode param works the same as in `iter_content`, with the
    same caveats.

    .. note:: This method is not reentrant safe.
    """

    pending: str | bytes | None = None

    for chunk in self.iter_content(
        chunk_size=chunk_size, decode_unicode=decode_unicode
    ):
        if pending is not None:
            # TODO: remove cast after iter_lines rewrite
            chunk = cast("str | bytes", pending + chunk)

        if delimiter:
            lines = chunk.split(delimiter)  # type: ignore[arg-type]
        else:
            lines = chunk.splitlines()

        if lines and lines[-1] and chunk and lines[-1][-1] == chunk[-1]:
            pending = lines.pop()
        else:
            pending = None

        yield from lines

    if pending is not None:
        yield pending

def json(self, **kwargs: Any) -> Any:
    r"""Decodes the JSON response body (if any) as a Python object.

    This may return a dictionary, list, etc. depending on what is in the response.

    :param \*\*kwargs: Optional arguments that ``json.loads`` takes.
    :raises requests.exceptions.JSONDecodeError: If the response body does not
        contain valid json.
    """

    if not self.encoding and self.content and len(self.content) > 3:
        # No encoding set. JSON RFC 4627 section 3 states we should expect
        # UTF-8, -16 or -32. Detect which one to use; If the detection or
        # decoding fails, fall back to `self.text` (using charset_normalizer to make
        # a best guess).
        encoding = guess_json_utf(self.content)
        if encoding is not None:
            try:
                return complexjson.loads(self.content.decode(encoding), **kwargs)
            except UnicodeDecodeError:
                # Wrong UTF codec detected; usually because it's not UTF-8
                # but some other 8-bit codec.  This is an RFC violation,
                # and the server didn't bother to tell us what codec *was*
                # used.
                pass
            except JSONDecodeError as e:
                raise RequestsJSONDecodeError(e.msg, e.doc, e.pos)

    try:
        return complexjson.loads(self.text, **kwargs)
    except JSONDecodeError as e:
        # Catch JSON-related errors and raise as requests.JSONDecodeError
        # This aliases json.JSONDecodeError and simplejson.JSONDecodeError
        raise RequestsJSONDecodeError(e.msg, e.doc, e.pos)

def to_key_val_list(
    value: _t.SupportsItems[_KT, _VT] | Iterable[tuple[_KT, _VT]] | None,
) -> list[tuple[_KT, _VT]] | None:
    """Take an object and test to see if it can be represented as a
    dictionary. If it can be, return a list of tuples, e.g.,

    ::

        >>> to_key_val_list([('key', 'val')])
        [('key', 'val')]
        >>> to_key_val_list({'key': 'val'})
        [('key', 'val')]
        >>> to_key_val_list('string')
        Traceback (most recent call last):
        ...
        ValueError: cannot encode objects that are not 2-tuples

    :rtype: list
    """
    if value is None:
        return None

    if isinstance(value, (str, bytes, bool, int)):
        raise ValueError("cannot encode objects that are not 2-tuples")

    if isinstance(value, _SupportsItems):
        return list(value.items())

    return list(value)

def trange(*args, **kwargs):
    """
    A shortcut for `tqdm.auto.tqdm(range(*args), **kwargs)`.
    """
    return tqdm(range(*args), **kwargs)

@contextmanager
def ensure_lock(tqdm_class, lock_name="", lock=None):
    """get (create if necessary) and then restore `tqdm_class`'s lock"""
    old_lock = getattr(tqdm_class, '_lock', None)  # don't create a new lock
    if lock is None:
        lock = old_lock or tqdm_class.get_lock()  # maybe create a new lock
    lock = getattr(lock, lock_name, lock)  # maybe subtype
    tqdm_class.set_lock(lock)
    yield lock
    if old_lock is None:
        del tqdm_class._lock
    else:
        tqdm_class.set_lock(old_lock)

def delete(self):
    """Deletes internal `message_id`."""
    try:
        future = self.submit(
            self.session.delete,
            f'{self.API}/channels/{self.channel_id}/messages/{self.message_id}',
            headers={'Authorization': f'Bot {self.token}', 'User-Agent': self.UA})
    except Exception as e:
        tqdm_auto.write(str(e))
    else:
        return future

def close(self):
    if self.disable:
        return
    super().close()
    if not (self.leave or (self.leave is None and self.pos == 0)):
        self.dio.delete()

def batched(iterable, n, total=None, tqdm_class=tqdm_auto, **kwargs):
    """Equivalent of `itertools.batched`."""
    if total is None:
        try:
            total = len(iterable)
        except (TypeError, AttributeError):
            pass
    return tqdm_class(itertools.batched(iterable, n), unit_scale=n,
                      total=(total+n-1) // n if total is not None else None,
                      **kwargs)

def close(self):
    if self.disable:
        return

    self.disable = True

    with self.get_lock():
        self._instances.remove(self)

    # Restore toolbars
    self.mpl.rcParams['toolbar'] = self.toolbar
    # Return to non-interactive mode
    if not self.wasion:
        self.plt.ioff()
    if self.leave:
        self.display()
    else:
        self.plt.close(self.fig)

def render(self, task):
    """Show data transfer speed."""
    speed = task.speed
    if speed is None:
        return Text(f"? {self.unit}/s", style="progress.data.speed")
    if self.unit_scale:
        unit, suffix = filesize.pick_unit_and_suffix(
            speed,
            ["", "K", "M", "G", "T", "P", "E", "Z", "Y"],
            self.unit_divisor,
        )
    else:
        unit, suffix = filesize.pick_unit_and_suffix(speed, [""], 1)
    precision = 0 if unit == 1 else 1
    return Text(f"{speed/unit:,.{precision}f} {suffix}{self.unit}/s",
                style="progress.data.speed")

def TRLock(*args, **kwargs):
    """threading RLock"""
    try:
        from threading import RLock
        return RLock(*args, **kwargs)
    except (ImportError, OSError):  # pragma: no cover
        pass

@classmethod
def get_lock(cls):
    """Get the global lock. Construct it if it does not exist."""
    if not hasattr(cls, '_lock'):
        cls._lock = TqdmDefaultWriteLock()
    return cls._lock

def __bool__(self):
    if self.total is not None:
        return self.total > 0
    if self.iterable is None:
        raise TypeError('bool() undefined when iterable == total == None')
    return bool(self.iterable)

@property
def format_dict(self):
    """Public API for read-only member access."""
    if self.disable and not hasattr(self, 'unit'):
        return defaultdict(lambda: None, {
            'n': self.n, 'total': self.total, 'elapsed': 0, 'unit': 'it'})
    if self.dynamic_ncols:
        self.ncols, self.nrows = self.dynamic_ncols(self.fp)
    return {
        'n': self.n, 'total': self.total,
        'elapsed': self._time() - self.start_t if hasattr(self, 'start_t') else 0,
        'ncols': self.ncols, 'nrows': self.nrows, 'prefix': self.desc,
        'ascii': self.ascii, 'unit': self.unit, 'unit_scale': self.unit_scale,
        'rate': self._ema_dn() / self._ema_dt() if self._ema_dt() else None,
        'bar_format': self.bar_format, 'postfix': self.postfix,
        'unit_divisor': self.unit_divisor, 'initial': self.initial,
        'colour': self.colour}

def display(self, *_, **__):
    self._tk_n_var.set(self.n)
    d = self.format_dict
    # remove {bar}
    d['bar_format'] = (d['bar_format'] or "{l_bar}<bar/>{r_bar}").replace(
        "{bar}", "<bar/>")
    msg = self.format_meter(**d)
    if '<bar/>' in msg:
        msg = "".join(re.split(r'\|?<bar/>\|?', msg, maxsplit=1))
    self._tk_text_var.set(msg)
    if not self._tk_dispatching:
        self._tk_window.update()

@staticmethod
def disable_on_exception(tqdm_instance, func):
    """
    Quietly set `tqdm_instance.miniters=inf` if `func` raises `errno=5`.
    """
    tqdm_instance = proxy(tqdm_instance)

    def inner(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except OSError as e:
            if e.errno != 5:
                raise
            try:
                tqdm_instance.miniters = float('inf')
            except ReferenceError:
                pass
        except ValueError as e:
            if 'closed' not in str(e):
                raise
            try:
                tqdm_instance.miniters = float('inf')
            except ReferenceError:
                pass
    return inner

def chunked(iterable, n, strict=False):
    """Break *iterable* into lists of length *n*:

        >>> list(chunked([1, 2, 3, 4, 5, 6], 3))
        [[1, 2, 3], [4, 5, 6]]

    By the default, the last yielded list will have fewer than *n* elements
    if the length of *iterable* is not divisible by *n*:

        >>> list(chunked([1, 2, 3, 4, 5, 6, 7, 8], 3))
        [[1, 2, 3], [4, 5, 6], [7, 8]]

    To use a fill-in value instead, see the :func:`grouper` recipe.

    If the length of *iterable* is not divisible by *n* and *strict* is
    ``True``, then ``ValueError`` will be raised before the last
    list is yielded.

    """
    if n is not None and n < 0:
        raise ValueError('n must be at least 0')

    iterator = iter(partial(take, n, iter(iterable)), [])
    if strict:
        if n is None:
            raise ValueError('n must not be None when using strict mode.')

        def ret():
            for chunk in iterator:
                if len(chunk) != n:
                    raise ValueError('iterable is not divisible by n.')
                yield chunk

        return ret()
    else:
        return iterator

def __contains__(self, value):
    if not self._validator(value):
        return False

    try:
        item = next(self[value])
    except StopIteration:
        return False
    else:
        self._cache[value].appendleft(item)

    return True

def _get_values(self, value):
    """
    Helper to yield items from the parent iterator that match *value*.
    Items that don't match are stored in the local cache as they
    are encountered.
    """
    while True:
        # If we've cached some items that match the target value, emit
        # the first one and evict it from the cache.
        if self._cache.get(value):
            yield self._cache[value].popleft()
        # Otherwise we need to advance the parent iterator to search for
        # a matching item, caching the rest.
        else:
            while True:
                try:
                    item = next(self._it)
                except StopIteration:
                    return
                item_value = self._key(item)
                if item_value == value:
                    if value not in self._cache:
                        self._cache[value] = deque()
                    yield item
                    break
                elif self._validator(item_value):
                    self._cache[item_value].append(item)

def longest_common_prefix(iterables):
    """Yield elements of the longest common prefix among given *iterables*.

    >>> ''.join(longest_common_prefix(['abcd', 'abc', 'abf']))
    'ab'

    """
    return (c[0] for c in takewhile(all_equal, zip(*iterables)))

def always_reversible(iterable):
    """An extension of :func:`reversed` that supports all iterables, not
    just those which implement the ``Reversible`` or ``Sequence`` protocols.

        >>> print(*always_reversible(x for x in range(3)))
        2 1 0

    If the iterable is already reversible, this function returns the
    result of :func:`reversed()`. If the iterable is not reversible,
    this function will cache the remaining items in the iterable and
    yield them in reverse order, which may require significant storage.
    """
    try:
        return reversed(iterable)
    except TypeError:
        return reversed(list(iterable))

def _extract_monotonic(iterator, indices):
    'Non-decreasing indices, lazily consumed'
    num_read = 0
    for index in indices:
        advance = index - num_read
        try:
            value = next(islice(iterator, advance, None))
        except ValueError:
            if advance != -1 or index < 0:
                raise ValueError(f'Invalid index: {index}') from None
        except StopIteration:
            raise IndexError(index) from None
        else:
            num_read += advance + 1
        yield value

def _extract_buffered(iterator, index_and_position):
    'Arbitrary index order, greedily consumed'
    buffer = {}
    iterator_position = -1
    next_to_emit = 0

    for index, order in index_and_position:
        advance = index - iterator_position
        if advance:
            try:
                value = next(islice(iterator, advance - 1, None))
            except StopIteration:
                raise IndexError(index) from None
            iterator_position = index

        buffer[order] = value

        while next_to_emit in buffer:
            yield buffer.pop(next_to_emit)
            next_to_emit += 1

def _lazy_is_generator(f: Callable) -> Callable[[], bool]:
    """
    Return a caching closure over callable f that returns whether f is a
    generator function.

    Not thread-safe but doesn't matter.
    """

    def is_gen() -> bool:
        import inspect

        try:
            if f not in _IS_GENERATOR_RESULTS:
                _IS_GENERATOR_RESULTS[f] = inspect.isgeneratorfunction(f)
        except TypeError:  # f is not hashable
            return inspect.isgeneratorfunction(f)

        return _IS_GENERATOR_RESULTS[f]

    return is_gen

def _make_attr_tuple_class(cls_name: str, attr_names: list[str]) -> type:
    """
    Create a tuple subclass to hold `Attribute`s for an `attrs` class.

    The subclass is a bare tuple with properties for names.

    class MyClassAttributes(tuple):
        __slots__ = ()
        x = property(itemgetter(0))
    """
    attr_class_name = f"{cls_name}Attributes"
    body = {}
    for i, attr_name in enumerate(attr_names):

        def getter(self, i=i):
            return self[i]

        body[attr_name] = property(getter)
    return type(attr_class_name, (tuple,), body)

def add_str(self):
    if not self._repr_added:
        msg = "__str__ can only be generated if a __repr__ exists."
        raise ValueError(msg)

    def __str__(self):
        return self.__repr__()

    self._cls_dict["__str__"] = self._add_method_dunders(__str__)
    return self

def _make_eq_script(attrs: list) -> tuple[str, dict]:
    """
    Create __eq__ method for *cls* with *attrs*.
    """
    attrs = [a for a in attrs if a.eq]

    lines = [
        "def __eq__(self, other):",
        "    if other.__class__ is not self.__class__:",
        "        return NotImplemented",
    ]

    globs = {}
    if attrs:
        lines.append("    return  (")
        for a in attrs:
            if a.eq_key:
                cmp_name = f"_{a.name}_key"
                # Add the key function to the global namespace
                # of the evaluated function.
                globs[cmp_name] = a.eq_key
                lines.append(
                    f"        {cmp_name}(self.{a.name}) == {cmp_name}(other.{a.name})"
                )
            else:
                lines.append(f"        self.{a.name} == other.{a.name}")
            if a is not attrs[-1]:
                lines[-1] = f"{lines[-1]} and"
        lines.append("    )")
    else:
        lines.append("    return True")

    script = "\n".join(lines)

    return script, globs

def _determine_setters(
    frozen: bool, slots: bool, base_attr_map: dict[str, type]
):
    """
    Determine the correct setter functions based on whether a class is frozen
    and/or slotted.
    """
    if frozen is True:
        if slots is True:
            return (), _setattr, _setattr_with_converter

        # Dict frozen classes assign directly to __dict__.
        # But only if the attribute doesn't come from an ancestor slot
        # class.
        # Note _inst_dict will be used again below if cache_hash is True

        def fmt_setter(
            attr_name: str, value_var: str, has_on_setattr: bool
        ) -> str:
            if _is_slot_attr(attr_name, base_attr_map):
                return _setattr(attr_name, value_var, has_on_setattr)

            return f"_inst_dict['{attr_name}'] = {value_var}"

        def fmt_setter_with_converter(
            attr_name: str,
            value_var: str,
            has_on_setattr: bool,
            converter: Converter,
        ) -> str:
            if has_on_setattr or _is_slot_attr(attr_name, base_attr_map):
                return _setattr_with_converter(
                    attr_name, value_var, has_on_setattr, converter
                )

            return f"_inst_dict['{attr_name}'] = {converter._fmt_converter_call(attr_name, value_var)}"

        return (
            ("_inst_dict = self.__dict__",),
            fmt_setter,
            fmt_setter_with_converter,
        )

    # Not frozen -- we can just assign directly.
    return (), _assign, _assign_with_converter

